synthetic_modified_files.search:
/* Main container */
.mt-timeline {
  height: 100%;
  overflow-y: auto;
  position: relative;
  background: var(--bg-color);
  scrollbar-color: var(--bg-hover-color) rgba(0, 0, 0, 0.1);
}

synthetic_modified_files.replace:
/* Main container */
.mt-timeline {
  height: 100%;
  overflow: visible;
  position: relative;
  background: var(--bg-color);
  scrollbar-color: var(--bg-hover-color) rgba(0, 0, 0, 0.1);
}
